import 'dart:convert';import 'package:flutter/material.dart';import '../../../core/api_client.dart';
class PremiumGenerationSettingsScreen extends StatefulWidget{const PremiumGenerationSettingsScreen({super.key});State<PremiumGenerationSettingsScreen> createState()=>_S();}
class _S extends State<PremiumGenerationSettingsScreen>{String mode='FIRST_DAY_OF_MONTH';bool enabled=true,loading=true;String? message;
Future<void> load()async{final r=await ApiClient().get('/v2/premium-generation/configuration');final j=jsonDecode(r.body);setState((){mode=(j['generation_mode']??j['generationMode']??'FIRST_DAY_OF_MONTH').toString();enabled=j['enabled']==true||j['enabled']==1;loading=false;});}
@override void initState(){super.initState();load();}
Future<void> save()async{await ApiClient().put('/v2/premium-generation/configuration',body:{'generationMode':mode,'enabled':enabled});setState(()=>message='Configuration saved');}
Future<void> backfill()async{final r=await ApiClient().post('/v2/premium-generation/backfill-six-periods',body:{});setState(()=>message='Backfill complete: ${r.body}');}
Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Automatic Premium Generation')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[SwitchListTile(value:enabled,onChanged:(v)=>setState(()=>enabled=v),title:const Text('Enable automatic generation')),RadioListTile(value:'FIRST_DAY_OF_MONTH',groupValue:mode,onChanged:(v)=>setState(()=>mode=v!),title:const Text('Generate on the 1st of each month')),RadioListTile(value:'MONTH_AFTER_LAST_PAYMENT',groupValue:mode,onChanged:(v)=>setState(()=>mode=v!),title:const Text('Generate one month after last paid period')),const SizedBox(height:16),FilledButton(onPressed:save,child:const Text('SAVE CONFIGURATION')),const SizedBox(height:12),OutlinedButton(onPressed:backfill,child:const Text('GENERATE MISSING PREMIUMS FOR PAST 6 PERIODS')),if(message!=null)Padding(padding:const EdgeInsets.only(top:16),child:Text(message!))]));}
